"""sample.log에서 ERROR 레벨 줄만 골라 마크다운 표로 출력한다."""
import re
import sys
from pathlib import Path

ERROR_RE = re.compile(
    r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) ERROR \[([^\]]+)\] (.*)$"
)


def parse_errors(path):
    """ERROR 레벨 줄을 {"time", "module", "message"} 딕셔너리 목록으로 반환한다."""
    rows = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = ERROR_RE.match(line.rstrip("\r\n"))
            if m:
                rows.append({"time": m.group(1), "module": m.group(2), "message": m.group(3)})
    return rows


def format_table(rows):
    lines = ["| time | module | message |", "|---|---|---|"]
    for r in rows:
        cells = [r["time"], r["module"], r["message"]]
        lines.append("| " + " | ".join(c.replace("|", "\\|") for c in cells) + " |")
    return "\n".join(lines)


if __name__ == "__main__":
    log = sys.argv[1] if len(sys.argv) > 1 else Path(__file__).parent / "sample.log"
    print(format_table(parse_errors(log)))

